const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const shanghai = ee.Geometry.Point([121.4737, 31.2304]);
  const date = '2013-08-07';

  // 2. Data Acquisition & Check
  // Try MOD11A1 (Terra) first
  let col = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(shanghai);

  let colSize = await col.size().getInfo();
  console.log(`MOD11A1 images found: ${colSize}`);

  // If no Terra data, try MYD11A1 (Aqua)
  if (colSize === 0) {
    col = ee.ImageCollection('MODIS/006/MYD11A1')
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(shanghai);

    colSize = await col.size().getInfo();
    console.log(`MYD11A1 images found: ${colSize}`);

    if (colSize === 0) {
      console.log("No MODIS LST data available for this date.");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Apply QA mask and get LST
  const img = col.first();

  // Apply QA mask (mandatory QA flags - bits 0-1 should be 00 for good quality)
  const qc = img.select('QC_Day');
  const mask = qc.bitwiseAnd(3).eq(0);

  const lst = img.select('LST_Day_1km')
    .updateMask(mask)
    .multiply(0.02); // Scale factor to get Kelvin

  // 4. Check pixel count
  const countResult = await lst.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: shanghai.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = countResult.LST_Day_1km || 0;
  console.log(`Valid pixels after QA masking: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid pixels after quality filtering.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculation - Get max temperature in the area
  const stats = await lst.reduceRegion({
    reducer: ee.Reducer.max(),
    geometry: shanghai.buffer(5000),
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTempK = stats.LST_Day_1km;

  // 6. Validation & Final Answer
  if (maxTempK === null || maxTempK === undefined) {
    console.log("Temperature calculation failed (null result).");
    console.log("<answer>C3</answer>");
    return;
  }

  const maxTempC = maxTempK - 273.15;

  // Validate temperature is in reasonable range
  if (maxTempC < -50 || maxTempC > 80) {
    console.log(`Invalid temperature: ${maxTempC.toFixed(2)}°C (out of range)`);
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Max LST in Shanghai area: ${maxTempC.toFixed(2)}°C`);
  console.log(`Threshold: 39°C`);

  if (maxTempC > 39) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
